import{_ as l,a0 as p,w as d,s as o,ao as r,I as n,x as s,a1 as a,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const v=JSON.parse('{"title":"過渡到 nftables | LCTT x X-CMD","titleTemplate":false,"description":"過渡到 nftables | LCTT (201910) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"過渡到 nftables | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"過渡到 nftables | LCTT (201910) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201910/20191021 Transition to Nftables","title":"過渡到 nftables","tag":"201910","desc":""},"relativePath":"201910/20191021 Transition to Nftables.md","filePath":"[post].md"}'),c={name:"201910/20191021 Transition to Nftables.md"};function f(h,e,u,g,b,k){const t=p("Link");return d(),o("div",null,[e[15]||(e[15]=r(`<h1 id="過渡到-nftables" tabindex="-1">過渡到 nftables <a class="header-anchor" href="#過渡到-nftables" aria-label="Permalink to “過渡到 nftables”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/201910/29/085827o8b7rbswjjr7ijsr.jpg" alt=""></p><blockquote><p>開源世界中的每個主要發行版都在演進，逐漸將 nftables 作為了默認防火牆。換言之，古老的 iptables 現在已經消亡。本文是有關如何構建 nftables 的教程。</p></blockquote><p>當前，有一個與 nftables 兼容的 iptables-nft 後端，但是很快，即使是它也不再提供了。另外，正如 Red Hat 開發人員所指出的那樣，有時它可能會錯誤地轉換規則。我們需要知道如何構建自己的 nftables，而不是依賴於 iptables 到 nftables 的轉換器。</p><p>在 nftables 中，所有地址族都遵循一個規則。與 iptables 不同，nftables 在用户空間中運行，iptables 中的每個模組都運行在內核（空間）中。它很少需要更新內核，並帶有一些新功能，例如映射、地址族和字典。</p><h3 id="地址族" tabindex="-1">地址族 <a class="header-anchor" href="#地址族" aria-label="Permalink to “地址族”">​</a></h3><p>地址族確定要處理的數據包的類型。在 nftables 中有六個地址族，它們是：</p><ul><li>ip</li><li>ipv6</li><li>inet</li><li>arp</li><li>bridge</li><li>netdev</li></ul><p>在 nftables 中，ipv4 和 ipv6 協議可以被合併為一個稱為 inet 的單一地址族。因此，我們不需要指定兩個規則：一個用於 ipv4，另一個用於 ipv6。如果未指定地址族，它將默認為 ip 協議，即 ipv4。我們感興趣的領域是 inet 地址族，因為大多數家庭用户將使用 ipv4 或 ipv6 協議。</p><h3 id="nftables" tabindex="-1">nftables <a class="header-anchor" href="#nftables" aria-label="Permalink to “nftables”">​</a></h3><p>典型的 nftables 規則包含三個部分：表、鏈和規則。</p><p>表是鏈和規則的容器。它們由其地址族和名稱來標識。鏈包含 inet/arp/bridge/netdev 等協議所需的規則，並具有三種類型：過濾器、NAT 和路由。nftables 規則可以從腳本加載，也可以在終端鍵入，然後另存為規則集。</p><p>對於家庭用户，默認鏈為過濾器。inet 系列包含以下鈎子：</p><ul><li>Input</li><li>Output</li><li>Forward</li><li>Pre-routing</li><li>Post-routing</li></ul><h3 id="使用腳本還是不用" tabindex="-1">使用腳本還是不用？ <a class="header-anchor" href="#使用腳本還是不用" aria-label="Permalink to “使用腳本還是不用？”">​</a></h3><p>最大的問題之一是我們是否可以使用防火牆腳本。答案是：這是你自己的選擇。這裏有一些建議：如果防火牆中有數百條規則，那麼最好使用腳本，但是如果你是典型的家庭用户，則可以在終端中鍵入命令，然後（保存並在重啓時）加載規則集。每種選擇都有其自身的優缺點。在本文中，我們將在終端中鍵入它們以構建防火牆。</p><p>nftables 使用一個名為 <code>nft</code> 的程序來添加、創建、列出、刪除和加載規則。確保使用以下命令將 nftables 與 conntrackd 和 netfilter-persistent 軟件包一起安裝，並刪除 iptables：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>apt-get install nftables conntrackd netfilter-persistent</span></span>
<span class="line"><span>apt-get purge iptables</span></span></code></pre></div><p><code>nft</code> 需要以 root 身份運行或使用 <code>sudo</code> 運行。使用以下命令分別列出、刷新、刪除規則集和加載腳本。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>nft list ruleset</span></span>
<span class="line"><span>nft flush ruleset</span></span>
<span class="line"><span>nft delete table inet filter</span></span>
<span class="line"><span>/usr/sbin/nft -f /etc/nftables.conf</span></span></code></pre></div><h3 id="輸入策略" tabindex="-1">輸入策略 <a class="header-anchor" href="#輸入策略" aria-label="Permalink to “輸入策略”">​</a></h3><p>就像 iptables 一樣，防火牆將包含三部分：輸入（<code>input</code>）、轉發（<code>forward</code>）和輸出（<code>output</code>）。在終端中，為輸入（<code>input</code>）策略鍵入以下命令。在開始之前，請確保已刷新規則集。我們的默認策略將會刪除所有內容。我們將在防火牆中使用 inet 地址族。將以下規則以 root 身份添加或使用 <code>sudo</code> 運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>nft add table inet filter</span></span>
<span class="line"><span>nft add chain inet filter input { type filter hook input priority 0 \\; counter \\; policy drop \\; }</span></span></code></pre></div><p>你會注意到有一個名為 <code>priority 0</code> 的東西。這意味着賦予該規則更高的優先級。掛鈎通常賦予負整數，這意味着更高的優先級。每個掛鈎都有自己的優先級，過濾器鏈的優先級為 0。你可以檢查 nftables Wiki 頁面以查看每個掛鈎的優先級。</p><p>要了解你計算機中的網絡接口，請運行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ip link show</span></span></code></pre></div><p>它將顯示已安裝的網絡接口，一個是本地主機、另一個是以太網端口或無線端口。以太網端口的名稱如下所示：<code>enpXsY</code>，其中 <code>X</code> 和 <code>Y</code> 是數字，無線端口也是如此。我們必須允許本地主機的流量，並且僅允許從互聯網建立的傳入連接。</p><p>nftables 具有一項稱為裁決語句的功能，用於解析規則。裁決語句為 <code>accept</code>、<code>drop</code>、<code>queue</code>、<code>jump</code>、<code>goto</code>、<code>continue</code> 和 <code>return</code>。由於這是一個很簡單的防火牆，因此我們將使用 <code>accept</code> 或 <code>drop</code> 處理數據包。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>nft add rule inet filter input iifname lo accept</span></span>
<span class="line"><span>nft add rule inet filter input iifname enpXsY ct state new, established, related accept</span></span></code></pre></div><p>接下來，我們必須添加規則以保護我們免受隱秘掃描。並非所有的隱秘掃描都是惡意的，但大多數都是。我們必須保護網絡免受此類掃描。第一組規則列出了要測試的 TCP 標誌。在這些標誌中，第二組列出了要與第一組匹配的標誌。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>nft add rule inet filter input iifname enpXsY tcp flags \\&amp; \\(syn\\|fin\\) == \\(syn\\|fin\\) drop</span></span>
<span class="line"><span>nft add rule inet filter input iifname enpXsY tcp flags \\&amp; \\(syn\\|rst\\) == \\(syn\\|rst\\) drop</span></span>
<span class="line"><span>nft add rule inet filter input iifname enpXsY tcp flags \\&amp; \\(fin\\|rst\\) == \\(fin\\|rst\\) drop</span></span>
<span class="line"><span>nft add rule inet filter input iifname enpXsY tcp flags \\&amp; \\(ack\\|fin\\) == fin drop</span></span>
<span class="line"><span>nft add rule inet filter input iifname enpXsY tcp flags \\&amp; \\(ack\\|psh\\) == psh drop</span></span>
<span class="line"><span>nft add rule inet filter input iifname enpXsY tcp flags \\&amp; \\(ack\\|urg\\) == urg drop</span></span></code></pre></div><p>記住，我們在終端中鍵入這些命令。因此，我們必須在一些特殊字符之前添加一個反斜槓，以確保終端能夠正確解釋該斜槓。如果你使用的是腳本，則不需要這樣做。</p><h3 id="關於-icmp-的警告" tabindex="-1">關於 ICMP 的警告 <a class="header-anchor" href="#關於-icmp-的警告" aria-label="Permalink to “關於 ICMP 的警告”">​</a></h3><p>互聯網控制消息協議（ICMP）是一種診斷工具，因此不應完全丟棄該流量。完全阻止 ICMP 的任何嘗試都是不明智的，因為它還會導致停止向我們提供錯誤消息。僅啓用最重要的控制消息，例如回聲請求、回聲應答、目的地不可達和超時等消息，並拒絕其餘消息。回聲請求和回聲應答是 <code>ping</code> 的一部分。在輸入策略中，我們僅允許回聲應答、而在輸出策略中，我們僅允許回聲請求。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>nft add rule inet filter input iifname enpXsY icmp type { echo-reply, destination-unreachable, time-exceeded } limit rate 1/second accept</span></span>
<span class="line"><span>nft add rule inet filter input iifname enpXsY ip protocol icmp drop</span></span></code></pre></div><p>最後，我們記錄並丟棄所有無效數據包。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>nft add rule inet filter input iifname enpXsY ct state invalid log flags all level info prefix \\”Invalid-Input: \\”</span></span>
<span class="line"><span>nft add rule inet filter input iifname enpXsY ct state invalid drop</span></span></code></pre></div><h3 id="轉發和輸出策略" tabindex="-1">轉發和輸出策略 <a class="header-anchor" href="#轉發和輸出策略" aria-label="Permalink to “轉發和輸出策略”">​</a></h3><p>在轉發和輸出策略中，默認情況下我們將丟棄數據包，僅接受已建立連接的數據包。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>nft add chain inet filter forward { type filter hook forward priority 0 \\; counter \\; policy drop \\; }</span></span>
<span class="line"><span>nft add rule inet filter forward ct state established, related accept</span></span>
<span class="line"><span>nft add rule inet filter forward ct state invalid drop</span></span>
<span class="line"><span>nft add chain inet filter output { type filter hook output priority 0 \\; counter \\; policy drop \\; }</span></span></code></pre></div><p>典型的桌面用户只需要端口 80 和 443 即可訪問互聯網。最後，允許可接受的 ICMP 協議並在記錄無效數據包時丟棄它們。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>nft add rule inet filter output oifname enpXsY tcp dport { 80, 443 } ct state established accept</span></span>
<span class="line"><span>nft add rule inet filter output oifname enpXsY icmp type { echo-request, destination-unreachable, time-exceeded } limit rate 1/second accept</span></span>
<span class="line"><span>nft add rule inet filter output oifname enpXsY ip protocol icmp drop</span></span>
<span class="line"><span>nft add rule inet filter output oifname enpXsY ct state invalid log flags all level info prefix \\”Invalid-Output: \\”</span></span>
<span class="line"><span>nft add rule inet filter output oifname enpXsY ct state invalid drop</span></span></code></pre></div><p>現在我們必須保存我們的規則集，否則重新啓動時它將丟失。為此，請運行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo nft list ruleset. &gt; /etc/nftables.conf</span></span></code></pre></div><p>我們須在引導時加載 nftables，以下將在 systemd 中啓用 nftables 服務：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo systemctl enable nftables</span></span></code></pre></div><p>接下來，編輯 nftables 單元文件以刪除 <code>Execstop</code> 選項，以避免在每次引導時刷新規則集。該文件通常位於 <code>/etc/systemd/system/sysinit.target.wants/nftables.service</code>。現在重新啓動nftables：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo systemctl restart nftables</span></span></code></pre></div><h3 id="在-rsyslog-中記錄日誌" tabindex="-1">在 rsyslog 中記錄日誌 <a class="header-anchor" href="#在-rsyslog-中記錄日誌" aria-label="Permalink to “在 rsyslog 中記錄日誌”">​</a></h3><p>當你記錄丟棄的數據包時，它們直接進入 syslog，這使得讀取該日誌文件非常困難。最好將防火牆日誌重定向到單獨的文件。在 <code>/var/log</code> 目錄中創建一個名為 <code>nftables</code> 的目錄，並在其中創建兩個名為 <code>input.log</code> 和 <code>output.log</code> 的文件，分別存儲輸入和輸出日誌。確保系統中已安裝 rsyslog。現在轉到 <code>/etc/rsyslog.d</code> 並創建一個名為 <code>nftables.conf</code> 的文件，其內容如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>:msg,regex,”Invalid-Input: “ -/var/log/nftables/Input.log</span></span>
<span class="line"><span>:msg,regex,”Invalid-Output: “ -/var/log/nftables/Output.log &amp; stop</span></span></code></pre></div><p>現在，我們必須確保日誌是可管理的。為此，使用以下代碼在 <code>/etc/logrotate.d</code> 中創建另一個名為 <code>nftables</code> 的文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/var/log/nftables/* { rotate 5 daily maxsize 50M missingok notifempty delaycompress compress postrotate invoke-rc.d rsyslog rotate &gt; /dev/null endscript }</span></span></code></pre></div><p>重新啓動 nftables。現在，你可以檢查你的規則集。如果你覺得在終端中鍵入每個命令很麻煩，則可以使用腳本來加載 nftables 防火牆。我希望本文對保護你的系統有用。</p><hr>`,55)),n("p",null,[e[1]||(e[1]=s("via: ",-1)),a(t,{href:"https://opensourceforu.com/2019/10/transition-to-nftables/"},{default:i(()=>[...e[0]||(e[0]=[s("https://opensourceforu.com/2019/10/transition-to-nftables/",-1)])]),_:1})]),n("p",null,[e[6]||(e[6]=s("作者：",-1)),a(t,{href:"https://opensourceforu.com/author/vijay-marcel/"},{default:i(()=>[...e[2]||(e[2]=[s("Vijay Marcel D",-1)])]),_:1}),e[7]||(e[7]=s(" 選題：",-1)),a(t,{href:"https://github.com/lujun9972"},{default:i(()=>[...e[3]||(e[3]=[s("lujun9972",-1)])]),_:1}),e[8]||(e[8]=s(" 譯者：",-1)),a(t,{href:"https://github.com/wxy"},{default:i(()=>[...e[4]||(e[4]=[s("wxy",-1)])]),_:1}),e[9]||(e[9]=s(" 校對：",-1)),a(t,{href:"https://github.com/wxy"},{default:i(()=>[...e[5]||(e[5]=[s("wxy",-1)])]),_:1})]),n("p",null,[e[12]||(e[12]=s("本文由 ",-1)),a(t,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...e[10]||(e[10]=[s("LCTT",-1)])]),_:1}),e[13]||(e[13]=s(" 原創編譯，",-1)),a(t,{href:"https://linux.cn/"},{default:i(()=>[...e[11]||(e[11]=[s("Linux中國",-1)])]),_:1}),e[14]||(e[14]=s(" 榮譽推出",-1))])])}const C=l(c,[["render",f]]);export{v as __pageData,C as default};
